/**
 * `bech32.convertbits`: regroup a sequence of integers from `frombits`-wide
 * units into `tobits`-wide units, optionally zero padding the tail.
 *
 * Behaviour reproduced from the library's observable interface, including the
 * three ways it can fail:
 *   * a value outside `[0, 2**frombits)`         -> returns None
 *   * a negative bit width                       -> ValueError: negative shift count
 *   * a None input (a previous call's failure)   -> TypeError: not iterable
 * The line numbers below are the ones the library reports in a traceback.
 */

import { leftShift, rightShift } from '../python/bitops.mjs';
import { PyTypeError, frame, inFrame, withFrame } from '../python/errors.mjs';

const MODULE_FILE = 'bech32/__init__.py';

/** Source lines of `convertbits` that can raise. */
const LINE = {
  maxValue: 88, // maxv = (1 << tobits) - 1
  maxAccumulator: 89, // max_acc = (1 << (frombits + tobits - 1)) - 1
  iteration: 90, // for value in data:
  rangeCheck: 91, // if value < 0 or (value >> frombits):
};

function libraryFrame(line) {
  return frame({ file: MODULE_FILE, line, func: 'convertbits' });
}

/**
 * @param {bigint[]|null} data
 * @param {bigint} frombits
 * @param {bigint} tobits
 * @param {boolean} [pad]
 * @returns {bigint[]|null}
 */
export function convertbits(data, frombits, tobits, pad = true) {
  let acc = 0n;
  let bits = 0n;
  const ret = [];
  const maxValue = inFrame(libraryFrame(LINE.maxValue), () => leftShift(1n, tobits) - 1n);
  const maxAccumulator = inFrame(
    libraryFrame(LINE.maxAccumulator),
    () => leftShift(1n, frombits + tobits - 1n) - 1n,
  );

  if (data === null || data === undefined) {
    throw withFrame(
      new PyTypeError("'NoneType' object is not iterable"),
      libraryFrame(LINE.iteration),
    );
  }

  for (const value of data) {
    const outOfRange = inFrame(
      libraryFrame(LINE.rangeCheck),
      () => value < 0n || rightShift(value, frombits) !== 0n,
    );
    if (outOfRange) return null;
    acc = ((acc << frombits) | value) & maxAccumulator;
    bits += frombits;
    while (bits >= tobits) {
      bits -= tobits;
      ret.push(rightShift(acc, bits) & maxValue);
    }
  }

  if (pad) {
    if (bits !== 0n) ret.push(leftShift(acc, tobits - bits) & maxValue);
  } else if (bits >= frombits || (leftShift(acc, tobits - bits) & maxValue) !== 0n) {
    return null;
  }
  return ret;
}
